package main
import "fmt"

func primo(n int) bool {
    if n <= 1 {
        return false
    }
    for i := 2; i*i <= n; i++ {
        if n%i == 0 {
            return false
        }

    }
    return true
} 
func main() {
    var n int
    fmt.Scan(&n)
    if primo(n){
        fmt.Println(1)
    } else {
        fmt.Println(0)
    }
}
